import{z as l,x as p,o as t,c as S,q as o,j as s,D as e,d as A,s as r,S as n}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"TCP 三次握手","description":"","frontmatter":{"title":"TCP 三次握手","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/tcp-handshake.md","filePath":"cs/tcp-handshake.md","lastUpdated":1791063341000}'),i={name:"cs/tcp-handshake.md"};function d(C,a,c,B,T,N){const E=p("Mermaid");return t(),S("div",null,[a[2]||(a[2]=o('<h1 id="tcp-三次握手" tabindex="-1">TCP 三次握手 <a class="header-anchor" href="#tcp-三次握手" aria-label="Permalink to &quot;TCP 三次握手&quot;">​</a></h1><div class="epigraph"><p>双方交换初始序号并确认，才能在不可靠的数据报上开始一条有状态的字节流。</p><footer>—— 据 Postel, RFC 793, Transmission Control Protocol, 1981 整理</footer></div><p><a href="/cs/udp-checksum">上一课</a>把数据报送到端口，没有约定「我们在流的第几个字节」。IP 会丢、会重，两端必须同步序号空间。缺口是 <strong>TCP 连接建立</strong>：三次握手，SYN、SYN-ACK、ACK。本课不把重传定时器与窗口写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>若一方直接发数据，对端不知道序号从哪起，也无法区分旧连接的迟到包。RFC 793：每端选初始序号（ISN），SYN 消耗一个序号。三次：A 的 SYN，B 的 SYN+ACK（确认 A 的 ISN+1 并带上 B 的 ISN），A 的 ACK。缺口是这次状态同步，不是拥塞控制。</p><p>同时打开与复位（RST）点名即可，状态机不全画。</p><p><span class="marginnote">三次才能让双方都收到对方的 ISN 并确认。两次不够：对端无法确认「你看见了我的 ISN」。ISN 应难以猜测，安全课再谈；本课只要求两端各有一个。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>被动端 <code>listen</code>；主动端 <code>connect</code> 发 SYN。内核为四元组分配控制块（TCB），状态从 SYN-SENT / SYN-RECEIVED 到 ESTABLISHED。握手段可以不带应用数据（经典），或带（TFO 等后话，不展开）。失败：超时重发 SYN，或收到 RST。</p>',9)),(t(),s(n,null,{default:e(()=>[r(E,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20SYN%5B%22A%3A%20SYN%2C%20seq%3Dx%22%5D%20--%3E%20SYNACK%5B%22B%3A%20SYN-ACK%2C%20seq%3Dy%2C%20ack%3Dx%2B1%22%5D%0A%20%20SYNACK%20--%3E%20ACK%5B%22A%3A%20ACK%2C%20ack%3Dy%2B1%22%5D%0A%20%20ACK%20--%3E%20EST%5B%22%E5%8F%8C%E6%96%B9%20ESTABLISHED%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[A(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=o('<p><span class="marginnote">数字实例：SYN 里的 seq=x 不是&quot;发了一个字节&quot;，而是宣布&quot;我的流从第 x 个字节起&quot;。SYN 本身占掉一个序号，所以对端的确认号写成 x+1——这就是&quot;SYN 消耗序号&quot;的具体含义。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>握手把无连接的 IP/UDP 世界换成有连接表的内核对象，为后课累计确认与窗口准备「当前期望序号」。它仍不保证之后的字节到达——那是重传课。与<a href="/cs/syscall-path">系统调用</a>接头：<code>connect</code>/<code>accept</code> 在握手完成前可阻塞，调度去跑别人。</p><p><a href="/cs/dhcp-nat">NAT</a> 在 SYN 时建表项；半开连接会占资源（SYN 洪泛是安全课）。</p><p>握手不一定一次走通。SYN 在路上丢失、或最后的 ACK 没送达时，两端各有一条重试与清理路径：</p>',5)),(t(),s(n,null,{default:e(()=>[r(E,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20C1%5B%22%E5%AE%A2%E6%88%B7%E7%AB%AF%E5%8F%91%20SYN%22%5D%20--%3E%20L%7B%22SYN%20%E5%88%B0%E8%BE%BE%E6%9C%8D%E5%8A%A1%E7%AB%AF%3F%22%7D%0A%20%20L%20--%3E%7C%22%E5%90%A6%22%7C%20RET%5B%22%E5%AE%A2%E6%88%B7%E7%AB%AF%E8%B6%85%E6%97%B6%2C%20%E9%87%8D%E5%8F%91%20SYN%22%5D%0A%20%20RET%20--%3E%20L%0A%20%20L%20--%3E%7C%22%E6%98%AF%22%7C%20S1%5B%22%E6%9C%8D%E5%8A%A1%E7%AB%AF%E5%BB%BA%E5%8D%8A%E5%BC%80%E8%A1%A8%E9%A1%B9%2C%20%E5%9B%9E%20SYN-ACK%22%5D%0A%20%20S1%20--%3E%20L2%7B%22%E7%AC%AC%E4%B8%89%E6%AC%A1%20ACK%20%E5%88%B0%E8%BE%BE%3F%22%7D%0A%20%20L2%20--%3E%7C%22%E5%90%A6%22%7C%20S2%5B%22%E6%9C%8D%E5%8A%A1%E7%AB%AF%E7%AD%89%E5%BE%85%E8%B6%85%E6%97%B6%E5%90%8E%E6%B8%85%E6%8E%89%E8%A1%A8%E9%A1%B9%22%5D%0A%20%20L2%20--%3E%7C%22%E6%98%AF%22%7C%20EST%5B%22%E5%8F%8C%E6%96%B9%E8%BF%9B%E5%85%A5%20ESTABLISHED%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[A(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=o('<p><span class="marginnote">直觉类比：NAT 看见 SYN 就登记&quot;有人进来了&quot;，但登记的人若一直不回来补确认，座位照样被占着——SYN 洪泛正是恶意灌满这张登记簿，让正常新客进不了门。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把四次挥手的 TIME_WAIT 写全，只承认连接还有拆除。不引入 QUIC 的 1-RTT；对照在 QUIC 课。也不把 TLS 握手并进三次里——应用明文 TCP 可以先建连接。序号如何覆盖丢失段，下一课。</p><p>ISN 随时间与随机性变化，减轻旧包落入新连接。同时打开是两边都发 SYN 的对称情形，RFC 793 允许，实现少见。</p><p>监听队列满时新 SYN 可被丢或回 RST，这是服务器容量，不是协议缺少第四次握手。</p><p><span class="marginnote">常见误区：容易以为第三次 ACK 丢失后连接就凭空失败。实际上它只是普通确认，服务端会重发 SYN-ACK 等你补上；真正失败的条件是重试次数用尽，而不是某一次包没到。</span></p><p>后课默认：ESTABLISHED 后双方有 ISN。字节的累计确认与超时重传，下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>三次握手同步双方 ISN（RFC 793）。</li><li>连接是内核状态，不是 IP 的性质。</li><li>丢失段如何重发是下一课。</li><li>出处：RFC 793；Kurose and Ross。</li></ul>',9))])}const u=l(i,[["render",d]]);export{_ as __pageData,u as default};
